import subprocess
DIR=ROOT/'docs/勘校修訂/2026-11-20完整裁決'
def git(*a):return subprocess.check_output(['git',*a],cwd=ROOT).decode()
def main():
 batches=[json.loads((DIR/(x+'.json')).read_text())for x in ['定字與既有核對','T15','T17']];base=batches[0]['基準提交'];assert hashlib.sha256((DIR/'使用者備份原檔.json').read_bytes()).hexdigest()==batches[0]['附件SHA256'];edits=[r for b in batches for r in b['完整舊新與SHA256']if r['檔案'].startswith('qi-zheng-si-yu/knowledge/')];expected={r['檔案']for r in edits};changed=set(git('-c','core.quotePath=false','diff','--name-only',base,'--','qi-zheng-si-yu/knowledge').splitlines());assert changed==expected
 for r in edits:
  raw=(ROOT/r['檔案']).read_bytes();assert hashlib.sha256(raw).hexdigest()==r['新SHA256']and raw.decode()==r['新全文']
  if r['舊全文']is not None:assert hashlib.sha256(r['舊全文'].encode()).hexdigest()==r['舊SHA256'];assert git('show',base+':'+r['檔案'])==r['舊全文']
 # 保留T15舊引文，T17只先作明列替換，再於文末追加。
 for r in batches[1]['完整舊新與SHA256']:assert r['新全文'].startswith(r['舊全文'])
 plan=json.loads((ROOT/'tools/review_decisions_data_20261120.json').read_text())
 for r in batches[2]['完整舊新與SHA256']:
  old=r['舊全文']
  for a,b in plan['T17現卡替換'].get(Path(r['檔案']).name,[]):old=old.replace(a,b,1)
  assert r['新全文'].startswith(old)
  extra=r['新全文'][len(old):];assert not any(x in extra for x in ['爵主台魁','將命三官','對入對拱','陰傷火命','錯命龍劫','反後正','（七？）','（聖？）','下一格','?','？'])
 # 全數T14欄位，不以舊候選逆推本輪已確認的新字。
 packet=json.loads((D/'命海16_T14本輪逐筆複核.json').read_text())['明細'];values={1:'玉璽星',2:'天暉星',3:'天纛',4:'天聰',5:'天濕星',6:'天琮',7:'困苦星',8:'天空',9:'主孤獨',10:'玉垣',11:'富貴',12:'天姬',13:'不淂地',14:'天坎',15:'主阻滯',16:'天亢',17:'天酷',18:'天桑',19:'不淂地',20:'天餙',21:'天璿',22:'主清廟',23:'天慘',24:'不淂地',25:'拍火同',26:'絕祿星',27:'主喜怒'}
 for r in packet:assert '\n\n'+values[int(r['編號'][-2:])]+'\n'in (K/r['卡片']).read_text(),r['編號']
 assert '\n\n享福\n\n'in (K/'亥宮孛圖列（星平總會命海）.md').read_text()
 assert '\n\n入廟\n\n'in (K/'卯宮月圖列（星平總會命海）.md').read_text()
 blank=['歲殿圖列·戊寅（星學綱目圖說下）.md','登籍圖列·己丑（星學綱目圖說下）.md']
 for n in blank:assert (K/n).read_text()==git('show',base+':qi-zheng-si-yu/knowledge/'+n)
 suidian=json.loads((ROOT/'docs/勘校修訂/2026-11-20歲殿16張回填.json').read_text())['明細']
 assert all((K/r['卡名']).read_text()==git('show',base+':qi-zheng-si-yu/knowledge/'+r['卡名'])for r in suidian)
 fs=json.loads((ROOT/'docs/勘校修訂/2026-11-20-T14伏尸使用者授權-伏尸.json').read_text());assert (K/fs['明細'][0]['卡名']).read_text()==fs['明細'][0]['新全文']
 structural=[];files=list(K.glob('*.md'))
 for p in files:
  t=p.read_text();s=sections(t);bad=[]
  if t.splitlines()[0]!='#七政四餘':bad.append('標籤')
  for f in FIELDS:
   if not s.get(f):bad.append(f)
  if not re.search(r'《[^》]+》',t):bad.append('缺書名')
  if not(re.search(r'第\s*\d+[^\n]*頁',t)or re.search(r'《楊國正七政四餘彙編》第\d+(?:[—–-]\d+)?段',t)):bad.append('缺授權定位')
  if bad:structural.append({'卡名':p.name,'問題':bad})
 # 本輪只查正在追溯的三個原書頁；機械抽取原文，不讀其他已完成頁。
 excerpts=[]
 for book,n,term in [('張果星宗',32,'以歲駕宮起甲'),('御定五星精義',111,'歲殿'),('三辰通載',45,'論登籍')]:
  text=pdf(book)[n-1].get_text();fold=norm(text);pos=fold.find(term);assert pos>=0;excerpts.append({'書名':book,'PDF實際頁碼':n,'定位':term,'文字層校對片段':fold[max(0,pos-15):pos+180],'限制':'此片段只為核原頁出處，未回填卡片，也未自動修復異體字或標點'})
 result={'日期':'2026-11-20','基準提交':base,'使用者附件SHA256核對通過':True,'本輪修改既有卡':sum(r['舊全文']is not None for r in edits),'本輪新增卡':sum(r['舊全文']is None for r in edits),'其餘舊卡異動':0,'卡片刪除':0,'總卡數':len(files),'T14逐題確認通過':27,'T07十五張已一致不重改':True,'原圖空白兩卡不動':True,'T22十二值已一致不重改':True,'T15保留全部舊引文':True,'T17限定替換後保留其餘舊文':True,'T15新增片段':sum(x.get('處理')=='依獨立格／直行原文追加'for x in batches[1]['處理明細']),'T17新增片段':sum(x.get('處理')=='依獨立格／直行原文追加'for x in batches[2]['處理明細']),'結構問題數':len(structural),'結構問題':structural,'庫內理論出處':excerpts,'證據界線':'E0檢查與使用者裁決落實；不是全書逐字獨立驗收，不宣稱階段1.5完成。'};save('完整裁決總驗證-2026-11-20.json',result);assert not structural
 md=['# 完整裁決執行總報告','','## 目錄','','- [已完成](#已完成)','- [讀序與去重](#讀序與去重)','- [原圖空白兩處：庫內理論查核](#原圖空白兩處庫內理論查核)','- [仍須確認四處](#仍須確認四處)','- [已確認圖糊而暫擱](#已確認圖糊而暫擱)','','## 已完成','','本輪修訂既有18卡、新增2卡，總19,798卡；無刪卡，其餘舊卡異動0。逐批舊全文、新全文、SHA256及patch存於[完整裁決留存目錄](../勘校修訂/2026-11-20完整裁決/)。附件原始JSON逐位元組保存，不以附件簡體字覆蓋使用者後續文字。','[本輪所有既有變動檔的完整舊新全文與SHA256](../勘校修訂/2026-11-20完整裁決/既有全部檔案舊新全文與SHA256.json)亦已集中保存，包含帳本及抽查紀錄；[集中差異](../勘校修訂/2026-11-20完整裁決/既有全部檔案差異.patch)。','','T14新增授權7卡已落實，全27筆逐題檢查符合本輪值；享福原註已有且未改，主阻滯、主喜怒維持。三處照原刻與使用者裁決記不淂地，不改成得或淨。辰宮月記天璿。','T07十五張與T22伏尸十二值在本輪前已一致，只核對、不重複修訂；[十五張原頁、紅框及舊新值表](完整裁決定字與十五歲殿核對-2026-11-20.md)。','CY-己巳貴元按使用者原圖讀值戌補卡，抽查紀錄更新為28項確認；外書木、水僅留歷史，不覆蓋戌。T21-1按後續答覆記簊金，不寫篡金／箕的斜線字串，也不補歸屬取法。','全庫標籤、四欄與出處定位檢查0問題；這不是每頁內容的獨立原文驗收。','','## 讀序與去重','','[T15逐條整理](完整裁決-T15逐條整理-2026-11-20.md)：6張命例卡追加42片段，舊引文全文保留；034等指定重複切片不重複收字，025／026等同文也只追加一次。','T15-004炁角十與下一格魁星分開；009按原圖補核為日女初，與下一格文星分開；032原圖轉180度可辨文星；074原圖轉270度可辨木昴六，未把昂一律替換成昴。016只收已可分開的下一格文星，本格疑字仍待定。','[T17逐條整理與讀序表](完整裁決-T17逐條整理-2026-11-20.md)：5張原卡追加112片段；橫框切到多條直行的，回原圖重整，不收爵主台魁、對入對拱、陰傷火命、錯命龍劫等橫向殘串。','優先修正火迎金龍→火迫金龍、先天執行→先天運行；其餘使用者已定且與現卡同句的命主化劫、正財弔照、男主入垣、羅犯男女及四十歲斢入後天卦不謬也作限定替換。原句全文保存在本批舊稿，不刪檔。','T17指定6筆卦象圖形與5筆重複切片只在候選處理中排除；不刪既有卡、卦名文字或原引文。分格詞逐段照錄，不把斜線、下一格或括號問號寫進卡。','','## 原圖空白兩處：庫內理論查核','','戊寅歲殿77–78頁、己丑登籍75–76頁兩張現卡均逐位元組不動。下面是他書方法的推算與適用限制，不是《綱目》原圖讀值。','','|庫內原書／PDF實際頁|核到的文字與限制|','|---|---|','|《張果星宗》第32頁〈歲殿／歲駕〉|「以歲駕宮起甲，順數至生年干」；生年支為歲駕。可核歲殿法，不直接列出己丑登籍的原表字值。|','|《御定五星精義》第111頁|歲殿條載「登籍近貴，亦主晚榮」，註從本生太歲宮起甲順數至年干；有歲殿與登籍用語關聯，但不能僅此一句聲稱所有登籍表都同法。|','|《三辰通載》第45頁〈論登籍〉|另以帝座、崇勳、天地合儀星說登籍；名義與條件須並列，不把它融合成一個無條件固定宮字。|','','戊寅歲殿：依《張果星宗》歲殿法，甲寅→乙卯→丙辰→丁巳→戊午，理論位置午。','己丑：歲殿法為甲丑→乙寅→丙卯→丁辰→戊巳→己午；只有在採本表歲殿／登籍共值、並以同一歲殿法求值的前提下，才能條件式列登籍午。此次核到的庫內頁未直接列「己丑登籍午」，不可說已找到該格原表。','因此兩處只在報告列理論值與出處，不另造原刻值、不覆寫空白、不把推算句新增為原文卡。','','## 仍須確認四處','','|編號|待確認內容|紅框原圖|','|---|---|---|','|T15-016|本格合尾後的數字是否七，及整格讀序；相鄰文星已另收|[原圖](../待裁決/原圖/T15-016.png)／[方向圖](../待裁決/原圖/完整裁決方向/T15-016-四方向.png)|','|T15-075|畢五之前的字是否聖，或另字|[原圖](../待裁決/原圖/T15-075.png)／[方向圖](../待裁決/原圖/完整裁決方向/T15-075-四方向.png)|','|T17-040|午後一字為巳、已、己或其他；不按宮位語境代填|[原圖](../待裁決/原圖/T17-040.png)／[方向圖](../待裁決/原圖/完整裁決方向/T17-040-四方向.png)|','|T17-082|末尾已／巳／己宮一字；整條先留報告，不把未定原字入卡|[原圖](../待裁決/原圖/T17-082.png)／[方向圖](../待裁決/原圖/完整裁決方向/T17-082-四方向.png)|','','T17-082使用者已定的全文暫存：「大限扣定拾壹歲欠貳佰壹拾天，換至丙辰年四月二十七日，上相品已宮」。只因最後一字仍待複核，沒有把它寫成已確認原文；其他確定項已完成。','','## 已確認圖糊而暫擱','','T15-022、T15-024及T17-119按使用者指示圖糊未確認，該格不收、不自行修字；不重複要求使用者猜字。尚未列在本輪裁決中的其他候選，沒有因附件名為完整裁決就自動視為已確認。','本輪裁決執行完成；仍在階段1.5，不進階段2。']
 (D/'完整裁決執行總報告-2026-11-20.md').write_text('\n'.join(md)+'\n');print(json.dumps({k:v for k,v in result.items()if k not in ['庫內理論出處','結構問題']},ensure_ascii=False))
if __name__=='__main__':main()
